message.content:
{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve an execution failure (such as a build error, backend error, or import error) that was surfaced by an earlier execution step.",
      "source_description": "An observed execution failure or error produced by a prior tool call.",
      "target_description": "A subsequent agent action intended to eliminate the cause of that failure."
    },
    {
      "name": "VERIFIES_CHANGE_EFFECTIVENESS",
      "definition": "After applying a code or configuration modification, the agent performs a follow-up check to confirm that the modification actually removed the targeted problem.",
      "source_description": "A modification that was just applied to the codebase or configuration.",
      "target_description": "A subsequent inspection or search that confirms whether the modification achieved its intended effect."
    },
    {
      "name": "RETRIES_OPERATION_AFTER_REPAIR",
      "definition": "After repairing the cause of an earlier failure, the agent re-executes the same operation that previously failed in order to confirm that it now succeeds.",
      "source_description": "An earlier operation or verification that failed.",
      "target_description": "A re-execution of that same operation following a repair."
    },
    {
      "name": "PROCEEDS_ON_SUCCESSFUL_RESULT",
      "definition": "A successful execution result is used as the precondition for advancing the workflow to the next validation or task phase.",
      "source_description": "A successful execution result such as a completed build, install, or passing verification.",
      "target_description": "A subsequent action that assumes that success and advances the workflow."
    },
    {
      "name": "USES_DIAGNOSTIC_SCAN_TO_SCOPE_REMEDIATION",
      "definition": "Findings from a diagnostic search that enumerates problematic occurrences are used to define the scope of a subsequent targeted modification, so the modification addresses exactly the identified patterns.",
      "source_description": "A diagnostic search result that lists problematic code occurrences or patterns.",
      "target_description": "A subsequent modification that targets the identified occurrences or patterns."
    }
  ]
}

